package com.cocinaCasera.ui;
import com.cocinaCasera.dao.InventarioDAO;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.SQLException;
/** Historial real consultado desde transaccion y detalle_transaccion. */
public class PanelHistorialTransaccion extends JPanel{
 private final DefaultTableModel modelo=new DefaultTableModel(new Object[]{"ID","Movimiento","Concepto","Cantidad / detalle","Fecha y hora"},0){public boolean isCellEditable(int r,int c){return false;}};
 public PanelHistorialTransaccion(){setLayout(new BorderLayout(18,18));setBackground(new Color(241,245,249));setBorder(BorderFactory.createEmptyBorder(25,30,25,30));JLabel t=new JLabel("Historial de Transacciones y Movimientos");t.setFont(new Font("Segoe UI",Font.BOLD,25));add(t,BorderLayout.NORTH);JTable tabla=new JTable(modelo);tabla.setRowHeight(29);tabla.getColumnModel().getColumn(3).setPreferredWidth(320);tabla.setAutoResizeMode(JTable.AUTO_RESIZE_ALL_COLUMNS);JPanel card=new JPanel(new BorderLayout(10,10));card.setBackground(Color.WHITE);card.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));card.add(new JScrollPane(tabla),BorderLayout.CENTER);JButton b=new JButton("Actualizar historial");b.addActionListener(e->actualizar());JPanel sur=new JPanel(new FlowLayout(FlowLayout.RIGHT));sur.add(b);card.add(sur,BorderLayout.SOUTH);add(card,BorderLayout.CENTER);actualizar();}
 public final void actualizar(){try{modelo.setRowCount(0);for(Object[] x:new InventarioDAO().historial())modelo.addRow(x);}catch(SQLException e){JOptionPane.showMessageDialog(this,"No se pudo consultar el historial: "+e.getMessage(),"MySQL",JOptionPane.ERROR_MESSAGE);}}
}
